class Solution:

	def smallestNumber(self, S, D):
		if S > 9 * D:
			return '-1'
		S = S - 1
		i = D - 1
		res = [''] * D
		while i >= 0:
			if S >= 10:
				res[i] = str(9)
				i -= 1
				S -= 9
			elif i != 0:
				res[i] = str(S)
				i -= 1
				S = 0
			else:
				res[i] = str(S + 1)
				break
		return ''.join(res)
